/**
 * `workspace.failed`, written like an error object (design 5.3.11).
 */
export const zWorkspaceFailed = z.object({
  code: zErrorCode,
  reason: zErrorReason.nullish(),
});

/**
 * Open enum: unknown values must be accepted. Known: local worktree
 */
export const zWorkspaceKind = z.union([z.enum(["local", "worktree"]), z.string()]);

/**
 * `session.upserted`: one session in the sidebar.
 */
export const zSessionSummary = z.object({
  agent: zAgentKind,
  branch: z.string().nullish(),
  error_code: zFailureCode.nullish(),
  last_activity_at: zTimestampMs,
  pending_interactions: z.int().gte(0).lte(4294967295),
  pending_kind: zPendingKind.nullish(),
  project_id: zProjectId,
  read_only: z.boolean(),
  session_id: zSessionId,
  status: zSessionStatus,
  title: z.string(),
  title_source: zTitleSource,
  unread: z.boolean(),
  workspace_kind: zWorkspaceKind,
});

export const zArchivedSession = z.object({
  archived_at: zTimestampMs,
  summary: zSessionSummary,
});

export const zIndexView = z.object({
  agents: zAgentsUpdated.nullish(),
  clients: zClientsUpdated.nullish(),
  elevations: z.record(z.string(), zElevationRequested),
  host: zHostUpdated.nullish(),
  projects: z.record(z.string(), zProjectUpserted),
  sessions: z.record(z.string(), zSessionSummary),
});

export const zSessionListArchivedResult = z.object({
  next: zArchivedCursor.nullish(),
  sessions: z.array(zArchivedSession),
});

export const zSessionWorkspace = z.object({
  base_ref: z.string().nullish(),
  branch: z.string().nullish(),
  kind: zWorkspaceKind,
  path: zWirePath,
});

/**
 * `session.configured`: on creation, a configuration change, a restore, or
 * a change of the project's trust state. A later one replaces an earlier one.
 */
export const zSessionConfigured = z.object({
  agent: zAgentKind,
  config: z.record(z.string(), z.string()),
  confirmation_required: zConfirmationRequired.nullish(),
  project_config: zProjectConfig,
  read_only: z.boolean(),
  workspace: zSessionWorkspace,
});

export const zSessionGetResult = z.object({
  archived_at: zTimestampMs.nullish(),
  summary: zSessionSummary,
  workspace: zSessionWorkspace,
});

export const zWorkspaceOpenParams = z.object({
  session_id: zSessionId,
  target: zOpenTarget,
});

/**
 * Open enum: unknown values must be accepted. Known: worktree_add checkout refresh
 */
export const zWorkspacePhase = z.union([
  z.enum(["worktree_add", "checkout", "refresh"]),
  z.string(),
]);

/**
 * `workspace.preparing`: while a worktree is created.
 */
export const zWorkspacePreparing = z.object({
  phase: zWorkspacePhase,
  progress: z.int().gte(0).lte(255).nullish(),
});

/**
 * `workspace.ready`.
 */
export const zWorkspaceReady = z.object({
  branch: z.string().nullish(),
  path: zWirePath,
});

export const zEvent = z.intersection(
  z.union([
    z.object({
      data: zProjectUpserted,
      type: z.literal("project.upserted"),
    }),
    z.object({
      data: zProjectRemoved,
      type: z.literal("project.removed"),
    }),
    z.object({
      data: zSessionSummary,
      type: z.literal("session.upserted"),
    }),
    z.object({
      data: zSessionRemoved,
      type: z.literal("session.removed"),
    }),
    z.object({
      data: zAgentsUpdated,
      type: z.literal("agents.updated"),
    }),
    z.object({
      data: zHostUpdated,
      type: z.literal("host.updated"),
    }),
    z.object({
      data: zClientsUpdated,
      type: z.literal("clients.updated"),
    }),
    z.object({
      data: zElevationRequested,
      type: z.literal("elevation.requested"),
    }),
    z.object({
      data: zElevationResolved,
      type: z.literal("elevation.resolved"),
    }),
    z.object({
      data: zNotificationIntent,
      type: z.literal("notification.intent"),
    }),
    z.object({
      data: zSessionConfigured,
      type: z.literal("session.configured"),
    }),
    z.object({
      data: zSessionCapabilities,
      type: z.literal("session.capabilities"),
    }),
    z.object({
      data: zWorkspacePreparing,
      type: z.literal("workspace.preparing"),
    }),
    z.object({
      data: zWorkspaceReady,
      type: z.literal("workspace.ready"),
    }),
    z.object({
      data: zWorkspaceFailed,
      type: z.literal("workspace.failed"),
    }),
    z.object({
      data: zTurnStarted,
      type: z.literal("turn.started"),
    }),
    z.object({
      data: zTurnCompleted,
      type: z.literal("turn.completed"),
    }),
    z.object({
      data: zItemStarted,
      type: z.literal("item.started"),
    }),
    z.object({
      data: zItemDelta,
      type: z.literal("item.delta"),
    }),
    z.object({
      data: zItemUpdated,
      type: z.literal("item.updated"),
    }),
    z.object({
      data: zItemCompleted,
      type: z.literal("item.completed"),
    }),
    z.object({
      data: zInteractionRequested,
      type: z.literal("interaction.requested"),
    }),
    z.object({
      data: zInteractionResolved,
      type: z.literal("interaction.resolved"),
    }),
    z.object({
      data: zQueueUpdated,
      type: z.literal("queue.updated"),
    }),
    z.object({
      data: zSnapshotRecorded,
      type: z.literal("snapshot.recorded"),
    }),
    z.object({
      data: zUsageUpdated,
      type: z.literal("usage.updated"),
    }),
    zUnknownEvent,
  ]),
  z.object({
    cause: zCause.nullish(),
    fallback: zFallback.nullish(),
    from: z.int().gte(0).lte(9007199254740991).nullish(),
    seq: z.int().gte(0).lte(9007199254740991),
    ts: zTimestampMs,
    v: z.int().gte(0).lte(4294967295),
  }),
);

/**
 * The `type` and `data` of an event. A snapshot or a history page is a
 * list of these, applied the same way as live events (ADR-06).
 */
export const zEventBody = z.union([
  z.object({
    data: zProjectUpserted,
    type: z.literal("project.upserted"),
  }),
  z.object({
    data: zProjectRemoved,
    type: z.literal("project.removed"),
  }),
  z.object({
    data: zSessionSummary,
    type: z.literal("session.upserted"),
  }),
  z.object({
    data: zSessionRemoved,
    type: z.literal("session.removed"),
  }),
  z.object({
    data: zAgentsUpdated,
    type: z.literal("agents.updated"),
  }),
  z.object({
    data: zHostUpdated,
    type: z.literal("host.updated"),
  }),
  z.object({
    data: zClientsUpdated,
    type: z.literal("clients.updated"),
  }),
  z.object({
    data: zElevationRequested,
    type: z.literal("elevation.requested"),
  }),
  z.object({
    data: zElevationResolved,
    type: z.literal("elevation.resolved"),
  }),
  z.object({
    data: zNotificationIntent,
    type: z.literal("notification.intent"),
  }),
  z.object({
    data: zSessionConfigured,
    type: z.literal("session.configured"),
  }),
  z.object({
    data: zSessionCapabilities,
    type: z.literal("session.capabilities"),
  }),
  z.object({
    data: zWorkspacePreparing,
    type: z.literal("workspace.preparing"),
  }),
  z.object({
    data: zWorkspaceReady,
    type: z.literal("workspace.ready"),
  }),
  z.object({
    data: zWorkspaceFailed,
    type: z.literal("workspace.failed"),
  }),
  z.object({
    data: zTurnStarted,
    type: z.literal("turn.started"),
  }),
  z.object({
    data: zTurnCompleted,
    type: z.literal("turn.completed"),
  }),
  z.object({
    data: zItemStarted,
    type: z.literal("item.started"),
  }),
  z.object({
    data: zItemDelta,
    type: z.literal("item.delta"),
  }),
  z.object({
    data: zItemUpdated,
    type: z.literal("item.updated"),
  }),
  z.object({
    data: zItemCompleted,
    type: z.literal("item.completed"),
  }),
  z.object({
    data: zInteractionRequested,
    type: z.literal("interaction.requested"),
  }),
  z.object({
    data: zInteractionResolved,
    type: z.literal("interaction.resolved"),
  }),
  z.object({
    data: zQueueUpdated,
    type: z.literal("queue.updated"),
  }),
  z.object({
    data: zSnapshotRecorded,
    type: z.literal("snapshot.recorded"),
  }),
  z.object({
    data: zUsageUpdated,
    type: z.literal("usage.updated"),
  }),
  zUnknownEvent,
]);

export const zHistoryPageResult = z.object({
  next: zHistoryCursor.nullish(),
  ops: z.array(zEventBody),
});

export const zStreamEventsParams = z.object({
  events: z.array(zEvent),
  stream: zStreamId,
});

export const zStreamSnapshotParams = z.object({
  at_seq: z.int().gte(0).lte(9007199254740991),
  epoch: z.int().gte(0).lte(9007199254740991),
  last: z.boolean(),
  ops: z.array(zEventBody),
  page: z.int().gte(0).lte(4294967295),
  stream: zStreamId,
});

/**
 * Where a new session works.
 */
export const zWorkspaceSpec = z.union([
  z.object({
    kind: z.literal("local"),
  }),
  zNewWorktree.and(
    z.object({
      kind: z.literal("worktree"),
    }),
  ),
  zUnknownMember.refine(
    (member) => typeof member.kind === "string" && !["local", "worktree"].includes(member.kind),
  ),
]);

export const zSessionCreateParams = z.object({
  agent: zAgentKind,
  command_id: zCommandId,
  config: zInitialConfig.nullish(),
  message: z.array(zPromptBlock),
  project_id: zProjectId,
  workspace: zWorkspaceSpec,
});

/**
 * The latest `workspace.*` event.
 */
export const zWorkspaceView = z.union([
  zWorkspacePreparing.and(
    z.object({
      state: z.literal("preparing"),
    }),
  ),
  zWorkspaceReady.and(
    z.object({
      state: z.literal("ready"),
    }),
  ),
  zWorkspaceFailed.and(
    z.object({
      state: z.literal("failed"),
    }),
  ),
]);

export const zSessionView = z.object({
  capabilities: zSessionCapabilities.nullish(),
  configured: zSessionConfigured.nullish(),
  detached: z.array(zRequestId),
  items: z.record(z.string(), zItemView),
  late_by_ref: z.record(z.string(), zItemId),
  queue: zQueueUpdated.nullish(),
  requests: z.record(z.string(), zRequestView),
  tail: z.array(zEntry),
  turns: z.array(zTurnView),
  usage: zUsageUpdated.nullish(),
  workspace: zWorkspaceView.nullish(),
});

/**
 * Open enum: unknown values must be accepted. Known: modified_files untracked_files operation_in_progress foreign_lock head_only_commits unpushed_commits initialized_submodules
 */
export const zWorktreeBlocker = z.union([
  z.enum([
    "modified_files",
    "untracked_files",
    "operation_in_progress",
    "foreign_lock",
    "head_only_commits",
    "unpushed_commits",
    "initialized_submodules",
  ]),
  z.string(),
]);

export const zWorktreeCheckParams = z.object({
  session_id: zSessionId,
});

/**
 * Open enum: unknown values must be accepted. Known: kept removed blocked
 */
export const zWorktreeOutcome = z.union([z.enum(["kept", "removed", "blocked"]), z.string()]);

export const zSessionArchiveResult = z.object({
  blockers: z.array(zWorktreeBlocker).optional(),
  worktree: zWorktreeOutcome,
});

/**
 * Worth telling the user, but no reason to keep the worktree.
 */
export const zWorktreeWarnings = z.object({
  case_only_dirty: z.boolean(),
  ignored_files: z.int().gte(0).lte(4294967295),
});

export const zWorktreeCheckResult = z.object({
  blockers: z.array(zWorktreeBlocker),
  removable: z.boolean(),
  warnings: zWorktreeWarnings,
});
